// LeadStats defines model for LeadStats.
type LeadStats struct {
	ByAdvocate []LeadStatsCategoryRevenue `json:"by_advocate"`
	ByCategory []LeadStatsCategoryRevenue `json:"by_category"`
	ByCreator  []LeadStatsCreatorRevenue  `json:"by_creator"`
	BySource   []LeadStatsSourceValue     `json:"by_source"`
	ByStatus   []LeadStatsCount           `json:"by_status"`

	// ByWeekday Leads by ISO day-of-week — key "1" (Monday) .. "7" (Sunday)
	ByWeekday []LeadStatsCount `json:"by_weekday"`

	// Funnel Cohort conversion, not a period ratio — cohort_leads is every client whose first-ever lead fell in the requested range; consulted_ever/ cased_ever count them regardless of when the consultation/case happened, even long after the range ends.
	Funnel LeadStatsFunnel `json:"funnel"`
	Range  struct {
		From    openapi_types.Date `json:"from"`
		GroupBy string             `json:"group_by"`
		To      openapi_types.Date `json:"to"`
	} `json:"range"`
	Totals struct {
		AvgTicket         float32 `json:"avg_ticket"`
		CaseFeeContracted float32 `json:"case_fee_contracted"`
		CaseOwed          float32 `json:"case_owed"`
		CasePaid          float32 `json:"case_paid"`
		CasesCompleted    int64   `json:"cases_completed"`
		CasesInProgress   int64   `json:"cases_in_progress"`
		Clients           int64   `json:"clients"`
		Consultations     int64   `json:"consultations"`
		Leads             int64   `json:"leads"`
		OrganicSessions   int64   `json:"organic_sessions"`
		RevenueBooked     float32 `json:"revenue_booked"`
		RevenueEarned     float32 `json:"revenue_earned"`
		RevenueLost       float32 `json:"revenue_lost"`
		SiteSessions      int64   `json:"site_sessions"`
	} `json:"totals"`
	Trend []LeadStatsBucket `json:"trend"`
}

